function dropShadows(filter) {
  const out = [];
  const re = /drop-shadow\(\s*((?:[^()]|\([^)]*\))*)\)/g; let m;
  while ((m = re.exec(filter || ''))) {
    const colM = /(?:rgba?|hsla?|hwb|lab|lch|oklab|oklch|color)\([^)]*\)|#[0-9a-f]{3,8}\b/i.exec(m[1]);
    const c = parseColor(colM ? colM[0] : 'rgba(0,0,0,1)');
    const nums = m[1].replace(colM ? colM[0] : '', '').match(/-?[\d.]+px|-?[\d.]+(?=\s|$)/g) || [];
    const [x = 0, y = 0, b = 0] = nums.map(parseFloat);
    if (c && c.a > 0) out.push({ type: 'DROP_SHADOW', color: c, offset: { x, y }, radius: b, spread: 0, visible: true, blendMode: 'NORMAL' });
  }
  return out;
}
