In ui.html, add a helper used by imageNode, videoNode and canvasNode (and later by svgNode for the SVG box-paint finding):

function replacedBox(el, cs, box, v, name, contentPaint) {
  const n = (p) => parseFloat(cs[p]) || 0;
  const iL = n('borderLeftWidth') + n('paddingLeft'), iR = n('borderRightWidth') + n('paddingRight');
  const iT = n('borderTopWidth') + n('paddingTop'),  iB = n('borderBottomWidth') + n('paddingBottom');
  // No insets: keep today's single RECT, so there are no extra layers.
  if (!(iL || iR || iT || iB)) return boxed('RECT', name, box, v, v.fills.concat(contentPaint));
  const f = boxed('FRAME', name, box, v, v.fills);   // background paints the border-box (background-clip default)
  f.clip = true;                                     // clips to the outer radii
  const cw = Math.max(0, box.w - iL - iR), ch = Math.max(0, box.h - iT - iB);
  f.children = [];
  if (cw > 0 && ch > 0) {
    const r = v.radii;
    const inner = r && {
      tl: r2(Math.max(0, r.tl - Math.max(iL, iT))), tr: r2(Math.max(0, r.tr - Math.max(iR, iT))),
      br: r2(Math.max(0, r.br - Math.max(iR, iB))), bl: r2(Math.max(0, r.bl - Math.max(iL, iB))),
    };
    f.children.push({ type: 'RECT', name: 'content', x: r2(iL), y: r2(iT), w: r2(cw), h: r2(ch),
      fills: [contentPaint], stroke: null, radii: inner && (inner.tl || inner.tr || inner.br || inner.bl) ? inner : null,
      effects: [], constraints: { horizontal: 'STRETCH', vertical: 'STRETCH' } });
  }
  return f;
}

