In ui.html, replace videoNode() with:

function videoNode(el, cs, box) {
  const v = boxVisual(el, cs, box);
  const mode = FIT_MODES[cs.objectFit] || 'FILL';
  let fill = null;
  if (S.opts.images) {
    if (el.poster) {
      fill = { type: 'IMAGE', ref: imageRef(el.poster, null), scaleMode: mode };
    } else if (el.readyState >= 2 && el.videoWidth > 0 && el.videoHeight > 0) {
      try {
        const c = document.createElement('canvas');
        c.width = el.videoWidth; c.height = el.videoHeight;
        c.getContext('2d').drawImage(el, 0, 0);
        fill = { type: 'IMAGE', ref: imageRef(c.toDataURL('image/png'), null), scaleMode: mode };
      } catch (e) { /* cross-origin video taints the canvas: fall through */ }
    }
  }
  // Without a poster or frame the browser shows only the CSS background; add the dark placeholder only when the element has none.
  if (!fill && !v.fills.length) fill = solid({ r: 0.1, g: 0.1, b: 0.1, a: 1 });
  return boxed('RECT', 'video', box, v, fill ? v.fills.concat(fill) : v.fills);
}

Notes: drawImage on a video without CORS succeeds, but toDataURL then throws, so the try/catch is required. The video's current frame is whatever the browser has decoded at measurement time (often the first frame when preload is metadata or auto). The harness check is dev/cases/media-embeds.html: the `.video-noposter` node should end up with only the #111827 SOLID.
